"use server";

import { updateTag } from "next/cache";
import { z } from "zod";
import { fail, ok, type ActionResult } from "@/lib/errors";
import { createClient } from "@/lib/supabase/server";
import { toFieldErrors } from "@/features/auth/schemas";
import { LISTINGS_TAG } from "@/features/discovery/queries";
import { dbFail, requireVendorActor } from "../lib/actor";
import {
  isOrgObjectPath,
  listingSchema,
  MAX_PHOTOS,
  SERVICE_STATUS_TRANSITIONS,
  toCateringRow,
  toServiceRow,
  toVenueRow,
  type ListingInput,
} from "../schemas";
import type { ServiceStatus } from "@/types/database";

const MEDIA_BUCKET = "listing-media";
const EDITORS = ["owner", "branch_manager"] as const;

/** Business category slug of a service category (decides venue / catering extension). */
async function businessSlugFor(supabase: Awaited<ReturnType<typeof createClient>>, serviceCategoryId: string) {
  const { data } = await supabase
    .from("service_categories")
    .select("business_categories(slug)")
    .eq("id", serviceCategoryId)
    .maybeSingle();
  return data?.business_categories?.slug ?? null;
}

/** Create or update a listing plus its typed category details. Returns the service id. */
export async function saveListing(input: ListingInput): Promise<ActionResult<string>> {
  const parsed = listingSchema.safeParse(input);
  if (!parsed.success) return fail("errors.invalidInput", toFieldErrors(parsed.error));
  const actor = await requireVendorActor(EDITORS);
  if (!actor.ok) return actor.result;
  const orgId = actor.ctx.membership.organization_id;
  const v = parsed.data;

  const supabase = await createClient();
  const row = toServiceRow(v);
  let serviceId = v.id;

  if (serviceId) {
    const { data, error } = await supabase
      .from("services")
      .update(row)
      .eq("id", serviceId)
      .eq("organization_id", orgId)
      .select("id");
    if (error) return dbFail(error);
    if (!data?.length) return fail("errors.forbidden");
  } else {
    const { data, error } = await supabase
      .from("services")
      .insert({ ...row, slug: "", organization_id: orgId, created_by: actor.ctx.user.id, status: "draft" }) // slug generated by trigger
      .select("id")
      .single();
    if (error) return dbFail(error);
    serviceId = data.id;
  }

  // Typed extension rows follow the category: keep the matching one, drop the other.
  const businessSlug = await businessSlugFor(supabase, v.serviceCategoryId);
  if (businessSlug === "venues" && v.venue) {
    const { error } = await supabase
      .from("venue_details")
      .upsert({ service_id: serviceId, organization_id: orgId, ...toVenueRow(v.venue) });
    if (error) return dbFail(error);
  } else {
    await supabase.from("venue_details").delete().eq("service_id", serviceId);
  }
  if (businessSlug === "catering" && v.catering) {
    const { error } = await supabase
      .from("catering_details")
      .upsert({ service_id: serviceId, organization_id: orgId, ...toCateringRow(v.catering) });
    if (error) return dbFail(error);
  } else {
    await supabase.from("catering_details").delete().eq("service_id", serviceId);
  }

  updateTag(LISTINGS_TAG);
  return ok(serviceId);
}

/** Publish / pause / archive with an explicit transition table. */
export async function setListingStatus(serviceId: string, next: ServiceStatus): Promise<ActionResult> {
  if (!z.uuid().safeParse(serviceId).success) return fail("errors.invalidInput");
  const actor = await requireVendorActor(EDITORS);
  if (!actor.ok) return actor.result;

  const supabase = await createClient();
  const { data: current } = await supabase
    .from("services")
    .select("status")
    .eq("id", serviceId)
    .eq("organization_id", actor.ctx.membership.organization_id)
    .maybeSingle();
  if (!current) return fail("errors.notFound");
  const allowed: readonly ServiceStatus[] = SERVICE_STATUS_TRANSITIONS[current.status];
  if (!allowed.includes(next)) return fail("errors.invalidInput");

  const { error } = await supabase.from("services").update({ status: next }).eq("id", serviceId);
  if (error) return dbFail(error);
  updateTag(LISTINGS_TAG);
  return ok(undefined);
}

// ---------- photos -------------------------------------------------------------------

/** Records photos the browser already uploaded to {org}/{uuid}.{ext}. First photo becomes the cover. */
export async function registerPhotos(serviceId: string, paths: string[]): Promise<ActionResult> {
  if (!z.uuid().safeParse(serviceId).success || paths.length === 0 || paths.length > MAX_PHOTOS) {
    return fail("errors.invalidInput");
  }
  const actor = await requireVendorActor(EDITORS);
  if (!actor.ok) return actor.result;
  const orgId = actor.ctx.membership.organization_id;
  if (!paths.every((p) => isOrgObjectPath(p, orgId))) return fail("errors.forbidden");

  const supabase = await createClient();
  const { data: existing, error: listError } = await supabase
    .from("service_media")
    .select("id, sort_order, is_cover")
    .eq("service_id", serviceId);
  if (listError) return dbFail(listError);
  if ((existing?.length ?? 0) + paths.length > MAX_PHOTOS) {
    await supabase.storage.from(MEDIA_BUCKET).remove(paths);
    return fail("vendor.listings.photosLimit");
  }

  const hasCover = existing?.some((m) => m.is_cover) ?? false;
  const start = Math.max(-1, ...(existing ?? []).map((m) => m.sort_order)) + 1;
  const { error } = await supabase.from("service_media").insert(
    paths.map((path, i) => ({
      service_id: serviceId,
      organization_id: orgId,
      storage_path: path,
      sort_order: start + i,
      is_cover: !hasCover && i === 0,
    })),
  );
  if (error) {
    await supabase.storage.from(MEDIA_BUCKET).remove(paths);
    return dbFail(error);
  }
  updateTag(LISTINGS_TAG);
  return ok(undefined);
}

export async function setCoverPhoto(mediaId: string): Promise<ActionResult> {
  if (!z.uuid().safeParse(mediaId).success) return fail("errors.invalidInput");
  const actor = await requireVendorActor(EDITORS);
  if (!actor.ok) return actor.result;

  const supabase = await createClient();
  const { data: media } = await supabase.from("service_media").select("service_id").eq("id", mediaId).maybeSingle();
  if (!media) return fail("errors.notFound");
  // Clear first: a partial unique index allows only one cover per listing.
  const { error: clearError } = await supabase
    .from("service_media")
    .update({ is_cover: false })
    .eq("service_id", media.service_id)
    .eq("is_cover", true);
  if (clearError) return dbFail(clearError);
  const { error } = await supabase.from("service_media").update({ is_cover: true }).eq("id", mediaId);
  if (error) return dbFail(error);
  updateTag(LISTINGS_TAG);
  return ok(undefined);
}

export async function deletePhoto(mediaId: string): Promise<ActionResult> {
  if (!z.uuid().safeParse(mediaId).success) return fail("errors.invalidInput");
  const actor = await requireVendorActor(EDITORS);
  if (!actor.ok) return actor.result;

  const supabase = await createClient();
  const { data: media } = await supabase
    .from("service_media")
    .select("service_id, storage_path, is_cover")
    .eq("id", mediaId)
    .maybeSingle();
  if (!media) return fail("errors.notFound");

  const { error } = await supabase.from("service_media").delete().eq("id", mediaId);
  if (error) return dbFail(error);
  await supabase.storage.from(MEDIA_BUCKET).remove([media.storage_path]);

  if (media.is_cover) {
    const { data: next } = await supabase
      .from("service_media")
      .select("id")
      .eq("service_id", media.service_id)
      .order("sort_order")
      .limit(1)
      .maybeSingle();
    if (next) await supabase.from("service_media").update({ is_cover: true }).eq("id", next.id);
  }
  updateTag(LISTINGS_TAG);
  return ok(undefined);
}
